class Solution:
    def resultGrid(self, image: List[List[int]], threshold: int) -> List[List[int]]:
        m, n = len(image), len(image[0])
        avg = [[0] * n for _ in range(m)]
        cnt = [[0] * n for _ in range(m)]
        def valid(r, c):
            for i in range(r, r + 3):
                for j in range(c, c + 2):
                    if abs(image[i][j] - image[i][j + 1]) > threshold:
                        return False
                    if abs(image[i][j] - image[i + 1][j]) > threshold:
                        return False
            return True
        for r in range(m - 2):
            for c in range(n - 2):
                if valid(r, c):
                    s = sum(sum(image[i][c:c + 3]) for i in range(r, r + 3)) // 9
                    for i in range(r, r + 3):
                        for j in range(c, c + 3):
                            avg[i][j] += s
                            cnt[i][j] += 1
        return [[avg[i][j] // cnt[i][j] if cnt[i][j] else image[i][j] for j in range(n)] for i in range(m)]

