class Solution {
public:
    vector<vector<int>> resultGrid(vector<vector<int>>& image, int threshold) {
        int m = image.size(), n = image[0].size();
        vector<vector<long long>> avg(m, vector<long long>(n, 0));
        vector<vector<int>> cnt(m, vector<int>(n, 0)), res = image;
        auto valid = [&](int r, int c) {
            for (int i = r; i < r + 3; i++)
                for (int j = c; j < c + 2; j++) {
                    if (abs(image[i][j] - image[i][j + 1]) > threshold) return false;
                    if (abs(image[i][j] - image[i + 1][j]) > threshold) return false;
                }
            return true;
        };
        for (int r = 0; r + 2 < m; r++)
            for (int c = 0; c + 2 < n; c++) {
                if (!valid(r, c)) continue;
                int s = 0;
                for (int i = r; i < r + 3; i++)
                    for (int j = c; j < c + 3; j++) s += image[i][j];
                s /= 9;
                for (int i = r; i < r + 3; i++)
                    for (int j = c; j < c + 3; j++) { avg[i][j] += s; cnt[i][j]++; }
            }
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (cnt[i][j]) res[i][j] = avg[i][j] / cnt[i][j];
        return res;
    }
};

