class Solution:
    def resultGrid(self, image: List[List[int]], threshold: int) -> List[List[int]]:
        m, n = len(image), len(image[0])
        def pref(g):
            p = [[0] * (len(g[0]) + 1) for _ in range(len(g) + 1)]
            for i in range(len(g)):
                for j in range(len(g[0])):
                    p[i + 1][j + 1] = g[i][j] + p[i][j + 1] + p[i + 1][j] - p[i][j]
            return p
        H = [[int(j + 1 < n and abs(image[i][j] - image[i][j + 1]) <= threshold) for j in range(n)] for i in range(m)]
        V = [[int(i + 1 < m and abs(image[i][j] - image[i + 1][j]) <= threshold) for j in range(n)] for i in range(m)]
        PH, PV, S = pref(H), pref(V), pref(image)
        def rect(P, r1, c1, r2, c2):
            return P[r2 + 1][c2 + 1] - P[r1][c2 + 1] - P[r2 + 1][c1] + P[r1][c1]
        avg = [[0] * n for _ in range(m)]
        cnt = [[0] * n for _ in range(m)]
        for r in range(m - 2):
            for c in range(n - 2):
                if rect(PH, r, c, r + 2, c + 1) == 6 and rect(PV, r, c, r + 1, c + 2) == 6:
                    s = rect(S, r, c, r + 2, c + 2) // 9
                    for i in range(r, r + 3):
                        for j in range(c, c + 3):
                            avg[i][j] += s
                            cnt[i][j] += 1
        return [[avg[i][j] // cnt[i][j] if cnt[i][j] else image[i][j] for j in range(n)] for i in range(m)]

