                PH[i + 1][j + 1] = PH[i][j + 1] + PH[i + 1][j] - PH[i][j] + (j + 1 < n && abs(image[i][j] - image[i][j + 1]) <= threshold);
                PV[i + 1][j + 1] = PV[i][j + 1] + PV[i + 1][j] - PV[i][j] + (i + 1 < m && abs(image[i][j] - image[i + 1][j]) <= threshold);
            }
