class Solution {
    public int[][] resultGrid(int[][] image, int threshold) {
        int m = image.length, n = image[0].length;
        long[][] PH = new long[m + 1][n + 1], PV = new long[m + 1][n + 1], S = new long[m + 1][n + 1];
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) {
                S[i + 1][j + 1] = image[i][j] + S[i][j + 1] + S[i + 1][j] - S[i][j];
                PH[i + 1][j + 1] = PH[i][j + 1] + PH[i + 1][j] - PH[i][j] + (j + 1 < n && Math.abs(image[i][j] - image[i][j + 1]) <= threshold ? 1 : 0);
                PV[i + 1][j + 1] = PV[i][j + 1] + PV[i + 1][j] - PV[i][j] + (i + 1 < m && Math.abs(image[i][j] - image[i + 1][j]) <= threshold ? 1 : 0);
            }
        int[][] avg = new int[m][n], cnt = new int[m][n], res = new int[m][n];
        for (int r = 0; r + 2 < m; r++)
            for (int c = 0; c + 2 < n; c++) {
                long h = PH[r + 3][c + 2] - PH[r][c + 2] - PH[r + 3][c] + PH[r][c];
                long v = PV[r + 2][c + 3] - PV[r][c + 3] - PV[r + 2][c] + PV[r][c];
                if (h != 6 || v != 6) continue;
                long s = (S[r + 3][c + 3] - S[r][c + 3] - S[r + 3][c] + S[r][c]) / 9;
                for (int i = r; i < r + 3; i++)
                    for (int j = c; j < c + 3; j++) { avg[i][j] += s; cnt[i][j]++; }
            }
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                res[i][j] = cnt[i][j] > 0 ? avg[i][j] / cnt[i][j] : image[i][j];
        return res;
    }
}

